{
is_shown_when_inactive = {
	has_variable = ywc_v03_initialized
	NOT = { has_variable = ywc_c02_started }
	OR = {
		AND = { c:NQG ?= this OR = { ywc_c02_case_ready_nqg = yes var:ywc_c02_case_open ?= 1 } }
		AND = { c:SHU ?= this OR = { ywc_c02_case_ready_shu = yes var:ywc_c02_case_open ?= 1 } }
		AND = { OR = { c:AMR ?= this c:SOL ?= this c:HUL ?= this } var:ywc_c02_case_open ?= 1 }
		AND = { c:MGL ?= this var:ywc_c02_case_open ?= 1 }
	}
}
possible = {
	has_variable = ywc_v03_initialized
	ywc_v03_has_capacity = yes
	NOT = { has_variable = ywc_c02_started }
	OR = {
		AND = { c:NQG ?= this ywc_c02_case_ready_nqg = yes }
		AND = { c:SHU ?= this ywc_c02_case_ready_shu = yes }
		AND = { OR = { c:AMR ?= this c:SOL ?= this c:HUL ?= this } var:ywc_c02_case_open ?= 1 }
		AND = { c:MGL ?= this var:ywc_c02_case_open ?= 1 }
	}
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c02_started } }
		set_variable = { name = ywc_c02_started value = 1 }
		set_variable = { name = ywc_c02_popup_epoch value = 0 }
		set_variable = { name = ywc_c02_wait_age value = 0 }
		change_variable = { name = ywc_v03_active_arc_count add = 1 }
		change_variable = { name = ywc_v03_visible_task_count add = 1 }
	}
	if = { limit = { NOT = { has_variable = ywc_c02_popup_epoch } } set_variable = { name = ywc_c02_popup_epoch value = 0 } }
	if = { limit = { c:NQG ?= this NOT = { has_variable = ywc_c02_role } } set_variable = { name = ywc_c02_role value = 1 } }
	if = { limit = { c:SHU ?= this NOT = { has_variable = ywc_c02_role } } if = { limit = { OR = { c:NQG ?= { has_variable = ywc_c02_started } c:AMR ?= { has_variable = ywc_c02_started } c:SOL ?= { has_variable = ywc_c02_started } c:HUL ?= { has_variable = ywc_c02_started } } } set_variable = { name = ywc_c02_role value = 2 } } else = { set_variable = { name = ywc_c02_role value = 4 } } }
	if = { limit = { OR = { c:AMR ?= this c:SOL ?= this c:HUL ?= this } NOT = { has_variable = ywc_c02_role } } if = { limit = { OR = { c:NQG ?= { has_variable = ywc_c02_started } c:SHU ?= { has_variable = ywc_c02_started } AND = { c:AMR ?= { has_variable = ywc_c02_started } c:SOL ?= { has_variable = ywc_c02_started } } AND = { c:AMR ?= { has_variable = ywc_c02_started } c:HUL ?= { has_variable = ywc_c02_started } } AND = { c:SOL ?= { has_variable = ywc_c02_started } c:HUL ?= { has_variable = ywc_c02_started } } } } set_variable = { name = ywc_c02_role value = 3 } } else = { set_variable = { name = ywc_c02_role value = 4 } } }
	if = { limit = { OR = { var:ywc_c02_role ?= 1 var:ywc_c02_role ?= 4 } NOT = { has_variable = ywc_c02_stage } }
		set_variable = { name = ywc_c02_case_open value = 1 }
		set_variable = { name = ywc_c02_stage value = 1100 }
		set_variable = { name = ywc_c02_pending value = 1100 }
	}
	if = { limit = { OR = { var:ywc_c02_role ?= 2 var:ywc_c02_role ?= 3 } NOT = { has_variable = ywc_c02_stage } } set_variable = { name = ywc_c02_stage value = 1118 } }
	if = { limit = { c:MGL ?= this NOT = { has_variable = ywc_c02_stage } } set_variable = { name = ywc_c02_stage value = 1118 } }
	if = { limit = { c:NQG ?= this OR = { var:ywc_c02_role ?= 1 var:ywc_c02_role ?= 4 } c:SHU ?= { is_country_alive = yes NOT = { has_variable = ywc_c02_case_open } NOT = { has_variable = ywc_c02_stage } } }
		c:SHU = { set_variable = { name = ywc_c02_case_open value = 1 } set_variable = { name = ywc_c02_role value = 2 } set_variable = { name = ywc_c02_popup_epoch value = 0 } set_variable = { name = ywc_c02_wait_age value = 0 } set_variable = { name = ywc_c02_stage value = 1118 } }
	}
}
on_monthly_pulse = {
	effect = {
		if = { limit = { OR = { var:ywc_c02_role ?= 1 var:ywc_c02_role ?= 4 } var:ywc_c02_stage ?= 1113 }
			change_variable = { name = ywc_c02_wait_age add = 1 }
			if = { limit = { OR = { ywc_c02_responses_resolved = yes var:ywc_c02_wait_age >= 12 } } ywc_c02_init_after_responses = yes }
		}
		if = { limit = { OR = { var:ywc_c02_role ?= 2 var:ywc_c02_role ?= 3 } var:ywc_c02_stage ?= 1118 }
			change_variable = { name = ywc_c02_wait_age add = 1 }
			if = { limit = { OR = { ywc_c02_initiator_gone = yes var:ywc_c02_wait_age >= 36 } } ywc_c02_close_no_talks = yes }
		}
		if = { limit = { OR = { var:ywc_c02_role ?= 2 var:ywc_c02_role ?= 3 AND = { NOT = { has_variable = ywc_c02_role } var:ywc_c02_case_open ?= 1 } } OR = { var:ywc_c02_stage ?= 1102 var:ywc_c02_stage ?= 1103 } NOT = { ywc_c02_initiator_awaiting_responses = yes } }
			ywc_c02_close_no_talks = yes
		}
		if = { limit = { var:ywc_c02_stage ?= 1114 }
			change_variable = { name = ywc_c02_wait_age add = 1 }
			if = { limit = { OR = { ywc_c02_initiator_gone = yes var:ywc_c02_wait_age >= 24 } }
				set_variable = { name = ywc_c02_review_open value = 1 }
				set_variable = { name = ywc_c02_stage value = 1109 }
				set_variable = { name = ywc_c02_pending value = 1109 }
				set_variable = { name = ywc_c02_wait_age value = 0 }
				change_variable = { name = ywc_c02_popup_epoch add = 1 }
			}
		}
		if = { limit = { ywc_c02_nqg_delivery_1100 = yes } trigger_event = { id = ywc_crisis.1100 } }
		if = { limit = { ywc_c02_shu_delivery_1100 = yes } trigger_event = { id = ywc_crisis.1100 } }
		if = { limit = { ywc_c02_nqg_delivery_1101 = yes } trigger_event = { id = ywc_crisis.1101 } }
		if = { limit = { ywc_c02_shu_delivery_1101 = yes } trigger_event = { id = ywc_crisis.1101 } }
		if = { limit = { ywc_c02_shu_delivery_1102 = yes } trigger_event = { id = ywc_crisis.1102 } }
		if = { limit = { ywc_c02_mgl_delivery_1103 = yes } trigger_event = { id = ywc_crisis.1103 } }
	}
}
}

